head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil71804";
scwin.lastJob = "";  // 업무 처리명(confirmJob 이 채우고 alertJobResult 가 읽는다 — as-is 전역 LastJob)
scwin.form = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil71804.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "btn_Register", fn: function(){ return ((dma_readDataVO.get("lastSaveStatCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.lastSaveStatCd"); })()) < '3'); } }, { id: "btn_Register_2", fn: function(){ return ((dma_readDataVO.get("lastSaveStatCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.lastSaveStatCd"); })()) >='3'); } }, { id: "btn_DigitalSub", fn: function(){ return ((dma_readDataVO.get("lastSaveStatCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.lastSaveStatCd"); })()) >='4' && (dma_readDataVO.get("applStatusCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.applStatusCd"); })()) !== '03'); } }, { id: "if_secugrpId", fn: function(){ return ((dma_readDataVO.get("secugrpId") ?? (() => { throw new Error("unresolved:" + "readDataVO.secugrpId"); })()) ==='TC'); } }, { id: "tr_64", fn: function(){ return ((dma_readDataVO.get("secugrpId") ?? (() => { throw new Error("unresolved:" + "readDataVO.secugrpId"); })()) ==='TC'); } }, { id: "if_secugrpId_2", fn: function(){ return ((dma_readDataVO.get("secugrpId") ?? (() => { throw new Error("unresolved:" + "readDataVO.secugrpId"); })()) ==='IC'); } }, { id: "tr_75", fn: function(){ return ((dma_readDataVO.get("secugrpId") ?? (() => { throw new Error("unresolved:" + "readDataVO.secugrpId"); })()) ==='IC'); } }, { id: "tr_85", fn: function(){ return ((dma_readDataVO.get("secugrpId") ?? (() => { throw new Error("unresolved:" + "readDataVO.secugrpId"); })()) ==='IC'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.insertComma(3);

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil71804.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Register_onclick
 * @description 「저장」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Register_onclick = async function(e){
    try {
        await scwin.register()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil71804.btn_Register_onclick' }); }
};

/**
 * @method
