 */
scwin.btn_Register_2_onclick = async function(e){
    try {
        await scwin.register()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil71804.btn_Register_2_onclick' }); }
};

/**
 * @method
 * @name btn_DigitalSub_onclick
 * @description 「제출」 클릭 이벤트
