 * @hidden N
 */
scwin.btn_DigitalSub_onclick = async function(e){
    try {
        await scwin.digitalSub()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil71804.btn_DigitalSub_onclick' }); }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「목록보기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function(e){
    try {
        await scwin.search()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil71804.btn_Search_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_DigitalChangePage
 * @description Digital Change Page 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_DigitalChangePage = async function () {
    const sbmOptions = {
        id: "tx_fn_DigitalChangePage",
        method: "post",
        action: "/digital/DigitalList.do",
        ref: "dma_DigitalChangePageReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_Register
 * @description Register 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Register = async function () {
    const sbmOptions = {
        id: "tx_fn_Register",
