///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name digitalChangePage
 * @description digital Change Page 처리
 * @param {*} tab tab
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.digitalChangePage = async function (tab) {
    scwin.form = (document.digitalListForm || { elements: [] });
    const lastSaveStatCdInt = parseInt($c.util.getComponent('dma_DigitalChangePageReq').get('lastSaveStatCd'));
    if (lastSaveStatCdInt === 0 && tab > 1) {
        await $c.win.alert('발행증권에 관한 사항을 먼저 저장해주세요.');
        return;
    } else {
        if (lastSaveStatCdInt === 1 && tab > 2) {
            await $c.win.alert('상장신청인에 관한 사항을 먼저 저장해주세요.');
            return;
        } else {
            if (lastSaveStatCdInt === 2 && tab > 3) {
                await $c.win.alert('기타사항을 먼저 저장해주세요.');
                return;
            }
        }
    }
    if (tab === 1) {
        $c.util.getComponent('dma_DigitalChangePageReq').set('method', 'viewIsuTab');
    } else {
        if (tab === 2) {
            $c.util.getComponent('dma_DigitalChangePageReq').set('method', 'viewIsurTab');
        } else {
            if (tab === 3) {
                return;
            } else {
                $c.util.getComponent('dma_DigitalChangePageReq').set('method', 'viewAttachFileTab');
            }
        }
    }
    scwin.form.action = 'DigitalList.do';
    await scwin.tx_fn_DigitalChangePage();
};

/**
 * @method
 * @name register
 * @description register 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.register = async function () {
    if (!await scwin.confirmJob('I')) {
        return;
    }
    if ($c.util.getComponent('ipt_applStatusCd').getValue() === '02') {
        await $c.win.alert('반송된 신청입니다. 발행증권에 관한 사항 탭부터 다시 저장해야 합니다.');
        return;
    }
    scwin.removeComma(3);
    if (!fn_validate(3)) {
        scwin.insertComma(3);
        return;
    }
    if (!await scwin.valid()) {
        return;
    }
    $('input[name=comNm]').prop('disabled', '');
    $('input[name=trstCustdnNm]').prop('disabled', '');
    $('input[name=designComNm]').prop('disabled', '');
    scwin.form = (document.digitalListForm || { elements: [] });
    scwin.form.action = 'DigitalList.do';
    $c.util.getComponent('dma_DigitalChangePageReq').set('method', 'saveSrtyLpTab');
    await scwin.tx_fn_Register();
};

/**
 * @method
 * @name valid
 * @description valid 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.valid = async function () {
    if ($("input[name='comNm']").val() === '' || $("input[name='comNm']").val() == null) {
        await $c.win.alert("상장신청인은 필수입니다.");
        return false;
    }
    if ($("input[name='listApplChrgNm']").val() === '' || $("input[name='listApplChrgNm']").val() == null) {
        await $c.win.alert("상장신청인 담당자는 필수입니다.");
        return false;
    }
    if ($("input[name='listApplChrgTelNo']").val() === '' || $("input[name='listApplChrgTelNo']").val() == null) {
        await $c.win.alert("상장신청인 연락처는 필수입니다.");
        return false;
    }
    return true;
};

/**
 * @method
 * @name digitalSub
 * @description digital Sub 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.digitalSub = async function () {
    if (!await scwin.confirmJob('S')) {
        return;
    }
    scwin.form = (document.digitalListForm || { elements: [] });
    scwin.form.action = "DigitalList.do";
    $c.util.getComponent('dma_DigitalChangePageReq').set('method', 'submitList');
    await scwin.tx_fn_DigitalSub();
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    scwin.form = (document.digitalListForm || { elements: [] });
    scwin.form.action = "DigitalList.do";
    $c.util.getComponent('dma_DigitalChangePageReq').set('method', 'searchList');
    await scwin.tx_fn_Search();
};

